PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX ref: <https://brickschema.org/221113#>
SELECT ?z ?zn WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?zn .
} LIMIT 50

SELECT ?z ?label ?point ?pcls WHERE {
  ?z rdfs:label ?label .
  FILTER(CONTAINS(?label, "Perimeter_top_ZN_4"))
  OPTIONAL { ?z brick:hasPoint ?point . ?point a ?pcls . }
}

PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?point ?ts WHERE {
  ?point ref:hasExternalReference ?tsref .
  ?tsref ref:hasTimeseriesId ?ts .
  FILTER(CONTAINS(str(?point), "Zone_F4_Z05"))
}

